ALTER TABLE public.buy_orders ADD COLUMN cover_sector_image_id uuid REFERENCES public.sector_images(id) ON DELETE SET NULL, ADD COLUMN cover_image_path text, ADD COLUMN cover_image_name text, ADD COLUMN cover_uploaded_by uuid, ADD COLUMN cover_uploaded_at timestamptz;
ALTER TABLE public.buy_orders ADD CONSTRAINT buy_order_one_cover CHECK (cover_image_path IS NULL OR cover_sector_image_id IS NULL), ADD CONSTRAINT buy_order_cover_path CHECK (cover_image_path IS NULL OR cover_image_path ~ ('^buy-orders/' || id::text || '/[0-9a-f-]+\.jpg$'));
CREATE FUNCTION public.guard_buy_order_cover() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN
IF (TG_OP='INSERT' AND (NEW.cover_sector_image_id IS NOT NULL OR NEW.cover_image_path IS NOT NULL OR NEW.cover_image_name IS NOT NULL OR NEW.cover_uploaded_by IS NOT NULL OR NEW.cover_uploaded_at IS NOT NULL)) OR (TG_OP='UPDATE' AND (NEW.cover_sector_image_id,NEW.cover_image_path,NEW.cover_image_name,NEW.cover_uploaded_by,NEW.cover_uploaded_at) IS DISTINCT FROM (OLD.cover_sector_image_id,OLD.cover_image_path,OLD.cover_image_name,OLD.cover_uploaded_by,OLD.cover_uploaded_at)) THEN
IF auth.role() IS DISTINCT FROM 'service_role' AND auth.uid() IS NOT NULL AND NOT (public.is_control(auth.uid()) AND public.is_account_admin(auth.uid())) THEN RAISE EXCEPTION 'Admin only'; END IF;
END IF;
IF NEW.cover_sector_image_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.sector_images WHERE id=NEW.cover_sector_image_id AND sector_key=NEW.sector) THEN RAISE EXCEPTION 'Pick an image from this buy order sector'; END IF;
RETURN NEW; END $$;
CREATE TRIGGER guard_buy_order_cover BEFORE INSERT OR UPDATE OF cover_sector_image_id,cover_image_path,cover_image_name,cover_uploaded_by,cover_uploaded_at ON public.buy_orders FOR EACH ROW EXECUTE FUNCTION public.guard_buy_order_cover();
CREATE POLICY "Buy order uploads admin restriction" ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (bucket_id <> 'public-images' OR name NOT LIKE 'buy-orders/%' OR (public.is_control(auth.uid()) AND public.is_account_admin(auth.uid())));
CREATE POLICY "Buy order removal admin restriction" ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING (bucket_id <> 'public-images' OR name NOT LIKE 'buy-orders/%' OR (public.is_control(auth.uid()) AND public.is_account_admin(auth.uid())));
CREATE POLICY "Buy order update admin restriction" ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING (bucket_id <> 'public-images' OR name NOT LIKE 'buy-orders/%' OR (public.is_control(auth.uid()) AND public.is_account_admin(auth.uid()))) WITH CHECK (bucket_id <> 'public-images' OR name NOT LIKE 'buy-orders/%' OR (public.is_control(auth.uid()) AND public.is_account_admin(auth.uid())));